def eta(distance_m, speed_mps, delay_s, status):
    if status != "moving":
        return None
    if distance_m < 0:
        return None
    if distance_m == 0:
        return 0
    if speed_mps <= 0:
        return None
    return distance_m / speed_mps + delay_s

